import operator
import re
import sys

CMP = {
    '=': operator.eq,
    '<>': operator.ne,
    '<': operator.lt,
    '<=': operator.le,
    '>': operator.gt,
    '>=': operator.ge,
}


def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    sys.setrecursionlimit(max(sys.getrecursionlimit(), 100000))

    token_re = re.compile(r'\d+|[A-Z]+\d*|<>|<=|>=|[-+*/(),:=<>]')
    literal_re = re.compile(r'-?\d+')
    cache = {}
    active = set()

    def is_cell(t):
        return t is not None and t[0].isalpha() and t[-1].isdigit()

    def parse(text):
        toks = token_re.findall(text)
        pos = 0

        def peek():
            return toks[pos] if pos < len(toks) else None

        def take():
            nonlocal pos
            t = toks[pos]
            pos += 1
            return t

        def expect(t):
            if peek() != t:
                raise ValueError(f"expected {t!r}")
            take()

        def formula():
            node = term()
            while peek() in ('+', '-'):
                op = take()
                node = ('bin', op, node, term())
            return node

        def term():
            node = unary()
            while peek() in ('*', '/'):
                op = take()
                node = ('bin', op, node, unary())
            return node

        def unary():
            if peek() == '-':
                take()
                return ('neg', unary())
            return atom()

        def arg():
            if is_cell(peek()) and pos + 1 < len(toks) and toks[pos + 1] == ':':
                a = take()
                take()
                b = take()
                return ('range', a, b)
            return formula()

        def atom():
            t = take()
            if t.isdigit():
                return ('num', int(t))
            if t == '(':
                node = formula()
                expect(')')
                return node
            if is_cell(t):
                return ('ref', t)
            expect('(')
            if t == 'IF':
                left = formula()
                op = take()
                right = formula()
                expect(',')
                then = formula()
                expect(',')
                other = formula()
                expect(')')
                return ('if', left, op, right, then, other)
            args = [arg()]
            while peek() == ',':
                take()
                args.append(arg())
            expect(')')
            return ('call', t, args)

        return formula()

    def rng(node):
        a, b = node[1], node[2]
        c1, r1 = a[0], int(a[1:])
        c2, r2 = b[0], int(b[1:])
        out = []
        for r in range(min(r1, r2), max(r1, r2) + 1):
            for c in range(ord(min(c1, c2)), ord(max(c1, c2)) + 1):
                name = chr(c) + str(r)
                if name in cells:
                    v = cell_value(name)
                    if isinstance(v, str):
                        return v
                    out.append(v)
        return out

    def ev(node):
        k = node[0]
        if k == 'num':
            return node[1]
        if k == 'ref':
            return cell_value(node[1])
        if k == 'neg':
            v = ev(node[1])
            return v if isinstance(v, str) else -v
        if k == 'bin':
            left = ev(node[2])
            if isinstance(left, str):
                return left
            right = ev(node[3])
            if isinstance(right, str):
                return right
            op = node[1]
            if op == '+':
                return left + right
            if op == '-':
                return left - right
            if op == '*':
                return left * right
            if right == 0:
                return '#DIV/0!'
            q = abs(left) // abs(right)
            return q if (left < 0) == (right < 0) else -q
        if k == 'if':
            left = ev(node[1])
            if isinstance(left, str):
                return left
            right = ev(node[3])
            if isinstance(right, str):
                return right
            return ev(node[4]) if CMP[node[2]](left, right) else ev(node[5])

        fname, args = node[1], node[2]
        vals = []
        for a in args:
            if a[0] == 'range':
                x = rng(a)
                if isinstance(x, str):
                    return x
                vals.extend(x)
            else:
                x = ev(a)
                if isinstance(x, str):
                    return x
                vals.append(x)
        if fname == 'SUM':
            return sum(vals)
        if not vals:
            return 0
        return min(vals) if fname == 'MIN' else max(vals)

    def compute(text):
        text = text.strip()
        if literal_re.fullmatch(text):
            return int(text)
        return ev(parse(text[1:]))

    def cell_value(name):
        if name not in cells:
            return 0
        if name in cache:
            return cache[name]
        if name in active:
            return '#CYCLE!'
        active.add(name)
        v = compute(cells[name])
        active.discard(name)
        cache[name] = v
        return v

    return {name: cell_value(name) for name in cells}
